krpano.action:
		
        if (window.dyglCssRotate && window.adjustRotate) {
            if (!krpano.hlookatPre) krpano.hlookatPre = krpano.view.hlookat;
            if (!krpano.vlookatPre) krpano.vlookatPre = krpano.view.vlookat;

            var deltaH = krpano.view.hlookat - krpano.hlookatPre;
            var deltaV = krpano.view.vlookat - krpano.vlookatPre;

			krpano.view.hlookat = krpano.hlookatPre + deltaV;
			krpano.view.vlookat = krpano.vlookatPre - deltaH;
			
			if (krpano.view.vlookat > 89) {
                krpano.view.vlookat = 89;
            } else if (krpano.view.vlookat < -89) {
                krpano.view.vlookat = -89;
            }
        }
		krpano.hlookatPre = krpano.view.hlookat;
		krpano.vlookatPre = krpano.view.vlookat;

        rotateLookAt();

		showlog(false);
        if(autorotate.isrotating == false AND (view.hlookat != org_hlookat OR view.vlookat != org_vlookat) AND view.camroll == 270,
            add(count,1);
            trace(count);
            sub(tmph , view.hlookat,org_hlookat);
            sub(tmpv , view.vlookat,org_vlookat);
            trace(count, '--', tmph, '--', tmpv, '--',view.vlookat, '--',  view.hlookat);
            if(view.vlookat != 90 AND view.vlookat != -90, 
                sub(view.vlookat, tmph);
                sub(view.vlookat, tmpv);
                add(view.hlookat, tmpv);
                sub(view.hlookat, tmph);
                mod(view.hlookat, 360);
            );
            copy(org_vlookat,view.vlookat);
            copy(org_hlookat,view.hlookat);
            copy(org_tmph,tmph);
            copy(org_tmpv,tmpv);
        );

        panoViewChange();

 
        set("autorotate.enabled",true);
        set("autorotate.speed", 1.0);
		set("autorotate.waittime", 3);
        set("autorotate.horizon", 0);
		set(org_vlookat,0);
		set(org_hlookat,0);
		set(count,0);
        wait(0.1);
		if(startscene === null OR !scene[get(startscene)], copy(startscene,scene[0].name); );
			loadscene(get(startscene), null, MERGE, COLORBLEND(2.0, 0x000000, easeoutcubic));							
			if(startactions !== null, startactions() );

		for(
			set(i,0),
			i LT hotspot.count,
			inc(i),
			if(!hotspot[get(i)].enabled,
			  set(hotspot[get(i)].alpha, 0.0);
		  	)
        );

		registerattribute(xframes, calc((imagewidth / %1) BOR 0));
		registerattribute(yframes, calc((imageheight / %2) BOR 0));
		registerattribute(frames, calc(xframes * yframes));
		registerattribute(frame, 0);
 		set(crop, '0|0|%1|%2');
 		setinterval(calc('crop_anim_' + name), calc(1.0 / %3),
			if(loaded,
				inc(frame);
				if(frame GE frames, if(onlastframe !== null, onlastframe() ); set(frame,0); );
				mod(xpos, frame, xframes);
				div(ypos, frame, xframes);
				Math.floor(ypos);
				mul(xpos, %1);
				mul(ypos, %2);
				calc(crop, xpos + '|' + ypos + '|%1|%2');
			  ,
				clearinterval(calc('crop_anim_' + name));
			  );
		  );
